window.EINSPRUCH_AUSSAGEN2 = [
  {"nr": 1, "art": "S", "zeuge": "M60", "beweis": null, "etikett": null, "saetze": ["Ich stand links an der Ampel.", "Von meinem Platz ganz rechts konnte ich alles sehen.", "Der Laster fuhr bei Rot über die Kreuzung.", "Dann krachte es."], "falsch": 1},
  {"nr": 2, "art": "S", "zeuge": "F35", "beweis": null, "etikett": null, "saetze": ["Ich fuhr mit dem Fahrrad zur Arbeit.", "Es war ein ganz normaler Morgen.", "Ich stieg aus meinem Auto und rannte zu dem Verletzten.", "Er blutete am Kopf."], "falsch": 2},
  {"nr": 3, "art": "S", "zeuge": "M20", "beweis": null, "etikett": null, "saetze": ["Es war ein heißer Sommertag.", "Ich saß im Eiscafé an der Ecke.", "Ich trank gerade einen Kaffee.", "Wegen des Schneetreibens sah ich das Auto erst spät.", "Es fuhr viel zu schnell."], "falsch": 3},
  {"nr": 4, "art": "S", "zeuge": "F75", "beweis": null, "etikett": null, "saetze": ["Ich trage seit Jahren eine Brille.", "Eine Brille habe ich noch nie gebraucht.", "Ich habe das Kennzeichen genau gelesen.", "Es war ein grauer Kombi."], "falsch": 1},
  {"nr": 5, "art": "S", "zeuge": "M60", "beweis": null, "etikett": null, "saetze": ["Der Unfall war um acht Uhr morgens.", "Ich brachte gerade meine Enkelin zur Schule.", "Abends um acht ist dort ja kaum Verkehr.", "Das blaue Auto bog zu schnell ab."], "falsch": 2},
  {"nr": 6, "art": "S", "zeuge": "F35", "beweis": null, "etikett": null, "saetze": ["Ich war die Beifahrerin.", "Mein Mann fuhr ruhig und vorsichtig.", "Der andere kam von rechts.", "Ich hatte beide Hände am Lenkrad."], "falsch": 3},
  {"nr": 7, "art": "S", "zeuge": "M20", "beweis": null, "etikett": null, "saetze": ["Ich habe den Unfall nicht selbst gesehen.", "Ich sah genau, wie der Roller über die Haube flog.", "Ich hörte nur einen lauten Knall.", "Der Fahrer stand unter Schock."], "falsch": 1},
  {"nr": 8, "art": "S", "zeuge": "F75", "beweis": null, "etikett": null, "saetze": ["Ich wohne im dritten Stock.", "Vom Balkon sehe ich die Kreuzung.", "Ich wohne ebenerdig, deshalb stand ich direkt an der Straße.", "Ich rief sofort den Notarzt."], "falsch": 2},
  {"nr": 9, "art": "S", "zeuge": "M60", "beweis": null, "etikett": null, "saetze": ["Es war stockdunkel.", "Die Laterne war kaputt.", "Ich hörte Bremsen quietschen.", "Im hellen Licht der Laterne sah ich das Gesicht des Fahrers.", "Er sah sehr erschrocken aus."], "falsch": 3},
  {"nr": 10, "art": "S", "zeuge": "F35", "beweis": null, "etikett": null, "saetze": ["Ich bin mit 50 durch den Ort gefahren.", "Mit meinen 80 Sachen konnte ich nicht mehr bremsen.", "Ich halte mich immer an die Regeln."], "falsch": 1},
  {"nr": 11, "art": "S", "zeuge": "M20", "beweis": null, "etikett": null, "saetze": ["Das Auto war rot.", "Es parkte schräg auf dem Gehweg.", "Der weiße Wagen rollte dann langsam rückwärts."], "falsch": 2},
  {"nr": 12, "art": "S", "zeuge": "F75", "beweis": null, "etikett": null, "saetze": ["Ich war allein unterwegs.", "Ich ging zum Bäcker.", "Das Auto hielt nicht an.", "Mein Mann neben mir hat sofort die Polizei gerufen."], "falsch": 3},
  {"nr": 13, "art": "S", "zeuge": "M60", "beweis": null, "etikett": null, "saetze": ["Ich habe kein Handy.", "Ich habe den Unfall sofort mit dem Handy fotografiert.", "So etwas brauche ich nicht.", "Die Bilder habe ich der Polizei gegeben."], "falsch": 1},
  {"nr": 14, "art": "S", "zeuge": "F35", "beweis": null, "etikett": null, "saetze": ["Ich kam aus der Bäckerei.", "Da sah ich den Rempler auf dem Parkplatz.", "Ich saß die ganze Zeit in meinem Auto und habe nichts gesehen außer dem Rempler."], "falsch": 2},
  {"nr": 15, "art": "S", "zeuge": "M20", "beweis": null, "etikett": null, "saetze": ["Der Fahrer stieg sofort aus.", "Er entschuldigte sich bei allen.", "Das weiß ich noch genau.", "Er ist einfach weitergefahren, ohne anzuhalten."], "falsch": 3},
  {"nr": 16, "art": "S", "zeuge": "F75", "beweis": null, "etikett": null, "saetze": ["Es regnete in Strömen.", "Die Sonne schien, die Straße war trocken.", "Ich hatte meinen Schirm dabei."], "falsch": 1},
  {"nr": 17, "art": "S", "zeuge": "M60", "beweis": null, "etikett": null, "saetze": ["Ich bin zum ersten Mal diese Strecke gefahren.", "Das Schild habe ich übersehen.", "Ich fahre hier jeden Tag, ich kenne jede Kurve."], "falsch": 2},
  {"nr": 18, "art": "S", "zeuge": "F35", "beweis": null, "etikett": null, "saetze": ["Ich stand am Fußgängerüberweg.", "Das Kind lief bei Grün los.", "Daran erinnere ich mich gut.", "Die Ampel war für Fußgänger rot, das Kind hätte warten müssen."], "falsch": 3},
  {"nr": 19, "art": "S", "zeuge": "M20", "beweis": null, "etikett": null, "saetze": ["Wir waren zu dritt im Auto.", "Ich war alleine unterwegs und fuhr selbst.", "Ich saß hinten links."], "falsch": 1},
  {"nr": 20, "art": "S", "zeuge": "F75", "beweis": null, "etikett": null, "saetze": ["Der Motorradfahrer trug einen Helm.", "Ich sah ihn gut.", "Seine langen Haare wehten im Wind, weil er keinen Helm trug."], "falsch": 2},
  {"nr": 21, "art": "S", "zeuge": "M20", "beweis": null, "etikett": null, "saetze": ["Ich war den ganzen Abend zu Hause.", "Ich habe Videospiele gespielt.", "Da bin ich mir ganz sicher.", "Als ich aus der Disco kam, sah ich die Schlägerei."], "falsch": 3},
  {"nr": 22, "art": "S", "zeuge": "F75", "beweis": null, "etikett": null, "saetze": ["Ich habe den Mann nur von hinten gesehen.", "Sein Gesicht werde ich nie vergessen, er hatte einen Bart.", "Er lief schnell weg."], "falsch": 1},
  {"nr": 23, "art": "S", "zeuge": "M60", "beweis": null, "etikett": null, "saetze": ["Der Täter war klein und schmal.", "Er trug eine dunkle Jacke.", "Ein großer, kräftiger Mann, fast zwei Meter."], "falsch": 2},
  {"nr": 24, "art": "S", "zeuge": "F35", "beweis": null, "etikett": null, "saetze": ["Ich kenne den Angeklagten nicht.", "Ich sah ihn zum ersten Mal.", "Das kann ich beschwören.", "Wir sind seit der Schulzeit befreundet."], "falsch": 3},
  {"nr": 25, "art": "S", "zeuge": "M20", "beweis": null, "etikett": null, "saetze": ["Ich war nüchtern.", "Nach meinem fünften Bier ging ich nach Hause.", "Ich trinke keinen Alkohol.", "Ich habe alles klar gesehen."], "falsch": 1},
  {"nr": 26, "art": "S", "zeuge": "F75", "beweis": null, "etikett": null, "saetze": ["Ich schlafe immer mit Ohrstöpseln.", "Ich höre nachts gar nichts.", "Ich hörte genau, was die beiden draußen flüsterten."], "falsch": 2},
  {"nr": 27, "art": "S", "zeuge": "M60", "beweis": null, "etikett": null, "saetze": ["Das Geschäft war schon geschlossen.", "Es war nach 20 Uhr.", "So war es wirklich.", "Ich bin noch schnell reingegangen und habe Brot gekauft."], "falsch": 3},
  {"nr": 28, "art": "S", "zeuge": "F35", "beweis": null, "etikett": null, "saetze": ["Ich war zwei Wochen im Urlaub in Italien.", "An dem Tag habe ich den Einbruch beim Nachbarn beobachtet.", "Die Täter waren zu zweit."], "falsch": 1},
  {"nr": 29, "art": "S", "zeuge": "M20", "beweis": null, "etikett": null, "saetze": ["Ich habe nichts mitgenommen.", "Ich habe nur geschaut.", "Die Jacke habe ich bezahlen wollen, aber die Kasse war voll."], "falsch": 2},
  {"nr": 30, "art": "S", "zeuge": "F75", "beweis": null, "etikett": null, "saetze": ["Der Täter flüchtete zu Fuß.", "Er rannte über den Platz.", "Ich habe es selbst erlebt.", "Er stieg in sein Auto und raste davon."], "falsch": 3},
  {"nr": 31, "art": "S", "zeuge": "M60", "beweis": null, "etikett": null, "saetze": ["Ich habe die Polizei sofort angerufen.", "Die Polizei hat erst am nächsten Tag davon erfahren.", "Sie kam nach fünf Minuten."], "falsch": 1},
  {"nr": 32, "art": "S", "zeuge": "F35", "beweis": null, "etikett": null, "saetze": ["Der Streit begann im Treppenhaus.", "Ich hörte es durch die Tür.", "Die beiden stritten draußen auf dem Parkplatz, ich sah es vom Fenster."], "falsch": 2},
  {"nr": 33, "art": "S", "zeuge": "M20", "beweis": null, "etikett": null, "saetze": ["Ich habe den Mann nie berührt.", "Ich stand nur daneben.", "Daran gibt es keinen Zweifel.", "Ich habe ihn nur ganz leicht geschubst."], "falsch": 3},
  {"nr": 34, "art": "S", "zeuge": "F75", "beweis": null, "etikett": null, "saetze": ["Es war Samstagabend.", "Am Sonntagmorgen hörte ich den Lärm im Hof.", "Mein Fernsehkrimi lief gerade."], "falsch": 1},
  {"nr": 35, "art": "S", "zeuge": "M60", "beweis": null, "etikett": null, "saetze": ["Mein Portemonnaie war in der Jackentasche.", "Die Jacke hing am Stuhl.", "Ich hatte es die ganze Zeit in der Hand."], "falsch": 2},
  {"nr": 36, "art": "S", "zeuge": "F35", "beweis": null, "etikett": null, "saetze": ["Ich konnte nichts erkennen, es war zu dunkel.", "Nur Umrisse.", "Das habe ich damals schon so gesagt.", "Er hatte blaue Augen und eine Narbe am Kinn."], "falsch": 3},
  {"nr": 37, "art": "S", "zeuge": "M20", "beweis": null, "etikett": null, "saetze": ["Den Laden kenne ich gar nicht.", "Ich kaufe da jeden Tag meine Zigaretten.", "Ich war noch nie dort."], "falsch": 1},
  {"nr": 38, "art": "S", "zeuge": "F75", "beweis": null, "etikett": null, "saetze": ["Der Hund bellte die ganze Nacht.", "Ich konnte nicht schlafen.", "Es war eine völlig ruhige Nacht, ich habe durchgeschlafen."], "falsch": 2},
  {"nr": 39, "art": "S", "zeuge": "M60", "beweis": null, "etikett": null, "saetze": ["Ich bin allein zum Fest gegangen.", "Ich kannte dort niemanden.", "Das weiß ich noch genau.", "Meine Frau und ich haben den ganzen Abend getanzt."], "falsch": 3},
  {"nr": 40, "art": "S", "zeuge": "F35", "beweis": null, "etikett": null, "saetze": ["Ich habe das Graffiti am Montag entdeckt.", "Die Schmiererei war schon seit Wochen da.", "Am Wochenende war die Wand noch sauber."], "falsch": 1},
  {"nr": 41, "art": "S", "zeuge": "F35", "beweis": null, "etikett": null, "saetze": ["Ich arbeite seit fünf Jahren in der Firma.", "Ich kenne den Kläger gut.", "Ich habe erst letzten Monat dort angefangen."], "falsch": 2},
  {"nr": 42, "art": "S", "zeuge": "M60", "beweis": null, "etikett": null, "saetze": ["Der Kläger war nie krank.", "Er war immer da.", "Daran erinnere ich mich gut.", "Er fehlte ständig wegen Krankheit."], "falsch": 3},
  {"nr": 43, "art": "S", "zeuge": "M20", "beweis": null, "etikett": null, "saetze": ["Ich arbeite in der Frühschicht, von sechs bis vierzehn Uhr.", "Abends um zehn sah ich den Kläger noch an der Maschine, als ich dort arbeitete.", "Er war immer fleißig."], "falsch": 1},
  {"nr": 44, "art": "S", "zeuge": "F75", "beweis": null, "etikett": null, "saetze": ["Der Chef hat nie laut geschrien.", "Er ist ein ruhiger Mensch.", "Als er so laut brüllte, haben alle zugehört."], "falsch": 2},
  {"nr": 45, "art": "S", "zeuge": "F35", "beweis": null, "etikett": null, "saetze": ["Ich habe die Abmahnung selbst übergeben.", "Persönlich, im Büro.", "Da bin ich mir ganz sicher.", "Sie wurde per Post verschickt, ich war nicht dabei."], "falsch": 3},
  {"nr": 46, "art": "S", "zeuge": "M60", "beweis": null, "etikett": null, "saetze": ["Überstunden waren bei uns verboten.", "Wir blieben oft bis in die Nacht, um fertig zu werden.", "Um 16 Uhr gingen alle."], "falsch": 1},
  {"nr": 47, "art": "S", "zeuge": "M20", "beweis": null, "etikett": null, "saetze": ["Ich habe keinen Betriebsrat gewählt.", "Bei uns gibt es keinen.", "Unser Betriebsrat hat der Kündigung zugestimmt."], "falsch": 2},
  {"nr": 48, "art": "S", "zeuge": "F75", "beweis": null, "etikett": null, "saetze": ["Der Kläger war ein sehr guter Mitarbeiter.", "Immer zuverlässig.", "Das kann ich beschwören.", "Er war unzuverlässig, deshalb wurde er abgemahnt."], "falsch": 3},
  {"nr": 49, "art": "S", "zeuge": "F35", "beweis": null, "etikett": null, "saetze": ["Ich habe das Gespräch nicht mitgehört.", "Ich hörte jedes Wort, das der Chef sagte.", "Die Tür war zu."], "falsch": 1},
  {"nr": 50, "art": "S", "zeuge": "M60", "beweis": null, "etikett": null, "saetze": ["Die Firma hat über 50 Mitarbeiter.", "Wir sind ein großer Betrieb.", "Wir sind nur zu fünft, ein kleiner Familienbetrieb."], "falsch": 2},
  {"nr": 51, "art": "S", "zeuge": "M20", "beweis": null, "etikett": null, "saetze": ["Ich war an dem Tag im Homeoffice.", "Den ganzen Tag.", "So war es wirklich.", "In der Kantine sah ich, wie der Streit anfing."], "falsch": 3},
  {"nr": 52, "art": "S", "zeuge": "F75", "beweis": null, "etikett": null, "saetze": ["Das Gehalt kam immer pünktlich, nie ein Problem.", "Wir mussten oft monatelang auf unser Geld warten.", "Trotzdem arbeite ich gern dort."], "falsch": 1},
  {"nr": 53, "art": "S", "zeuge": "F35", "beweis": null, "etikett": null, "saetze": ["Ich bin die Vorgesetzte des Klägers.", "Ich habe ihn eingestellt.", "Mit dem Kläger hatte ich beruflich nie zu tun."], "falsch": 2},
  {"nr": 54, "art": "S", "zeuge": "M60", "beweis": null, "etikett": null, "saetze": ["Der Kläger hat selbst gekündigt.", "Er wollte gehen.", "Ich habe es selbst erlebt.", "Wir haben ihm gekündigt, weil er zu teuer war."], "falsch": 3},
  {"nr": 55, "art": "S", "zeuge": "M20", "beweis": null, "etikett": null, "saetze": ["Ich bin erst nach dem Vorfall gekommen.", "Ich sah, wie die Kiste ihm auf den Fuß fiel.", "Da war alles schon vorbei."], "falsch": 1},
  {"nr": 56, "art": "S", "zeuge": "M60", "beweis": null, "etikett": null, "saetze": ["Ich bin nie in der Wohnung gewesen.", "Ich kenne sie nicht.", "In der Küche war alles sauber, das habe ich gesehen."], "falsch": 2},
  {"nr": 57, "art": "S", "zeuge": "F35", "beweis": null, "etikett": null, "saetze": ["Die Mieterin hat immer pünktlich gezahlt.", "Nie ein Problem.", "Daran gibt es keinen Zweifel.", "Sie war ständig mit der Miete im Rückstand."], "falsch": 3},
  {"nr": 58, "art": "S", "zeuge": "F75", "beweis": null, "etikett": null, "saetze": ["Ich wohne direkt unter der Wohnung.", "Ich wohne im Nachbarhaus und habe nichts gehört.", "Ich höre jeden Schritt."], "falsch": 1},
  {"nr": 59, "art": "S", "zeuge": "M20", "beweis": null, "etikett": null, "saetze": ["Die Heizung lief den ganzen Winter.", "Es war warm.", "Im Januar mussten wir mit Jacken in der Wohnung sitzen."], "falsch": 2},
  {"nr": 60, "art": "S", "zeuge": "M60", "beweis": null, "etikett": null, "saetze": ["Ich habe nie einen Schlüssel zur Wohnung gehabt.", "Der Mieter war ausgezogen.", "Der Vermieter bat mich nachzusehen.", "Mit meinem Schlüssel habe ich die Tür aufgeschlossen."], "falsch": 3},
  {"nr": 61, "art": "S", "zeuge": "F35", "beweis": null, "etikett": null, "saetze": ["Bei der Versammlung waren alle Eigentümer da.", "Die Hälfte der Eigentümer fehlte.", "Jeder hat abgestimmt."], "falsch": 1},
  {"nr": 62, "art": "S", "zeuge": "F75", "beweis": null, "etikett": null, "saetze": ["Der Schimmel kam erst im Winter.", "Im Sommer war die Wand sauber.", "Der Schimmel war schon beim Einzug im Juli da."], "falsch": 2},
  {"nr": 63, "art": "S", "zeuge": "M20", "beweis": null, "etikett": null, "saetze": ["Ich habe mich nie über Lärm beschwert.", "Mich stört nichts.", "Das weiß ich noch genau.", "Ich habe mich jede Woche beim Vermieter beschwert."], "falsch": 3},
  {"nr": 64, "art": "S", "zeuge": "M60", "beweis": null, "etikett": null, "saetze": ["Die Wohnung hat zwei Zimmer.", "Die Kinder hatten jeder ein eigenes Zimmer, das Elternschlafzimmer kam noch dazu.", "Sie ist klein."], "falsch": 1},
  {"nr": 65, "art": "S", "zeuge": "F35", "beweis": null, "etikett": null, "saetze": ["Die Katze lebt seit einem Jahr dort.", "Sie stört niemanden.", "Die Mieterin hat die Katze erst letzte Woche bekommen."], "falsch": 2},
  {"nr": 66, "art": "S", "zeuge": "F75", "beweis": null, "etikett": null, "saetze": ["Der Hausmeister kam sofort.", "Noch am selben Tag.", "Daran erinnere ich mich gut.", "Wir haben drei Wochen auf den Hausmeister gewartet."], "falsch": 3},
  {"nr": 67, "art": "S", "zeuge": "M20", "beweis": null, "etikett": null, "saetze": ["Die Kaution habe ich bar bezahlt, bei der Unterschrift.", "Ich habe die Kaution überwiesen, das steht auf dem Kontoauszug.", "Eine Quittung habe ich nicht."], "falsch": 1},
  {"nr": 68, "art": "S", "zeuge": "M60", "beweis": null, "etikett": null, "saetze": ["Der Wintergarten wurde letzten Sommer gebaut.", "Er ist ganz aus Glas.", "Den Wintergarten gibt es schon seit zehn Jahren."], "falsch": 2},
  {"nr": 69, "art": "S", "zeuge": "F35", "beweis": null, "etikett": null, "saetze": ["Ich habe die Nebenkostenabrechnung nie bekommen.", "Ich habe beim Verwalter nachgefragt.", "Er hat nie geantwortet.", "Die Abrechnung habe ich gelesen und sofort widersprochen."], "falsch": 3},
  {"nr": 70, "art": "S", "zeuge": "F75", "beweis": null, "etikett": null, "saetze": ["Im Haus wohnen nur ältere Leute.", "Die vielen Kinder im Haus machen den ganzen Tag Lärm.", "Es ist sehr ruhig."], "falsch": 1},
  {"nr": 71, "art": "S", "zeuge": "M20", "beweis": null, "etikett": null, "saetze": ["Ich habe die Küche allein aufgebaut.", "Niemand hat geholfen.", "Mein Kollege und ich brauchten zu zweit den ganzen Tag."], "falsch": 2},
  {"nr": 72, "art": "S", "zeuge": "F35", "beweis": null, "etikett": null, "saetze": ["Ich habe den Vertrag nicht unterschrieben.", "Ich habe nur gelesen.", "Das kann ich beschwören.", "Nachdem ich unterschrieben hatte, kamen mir Zweifel."], "falsch": 3},
  {"nr": 73, "art": "S", "zeuge": "M60", "beweis": null, "etikett": null, "saetze": ["Die Waschmaschine war neu und originalverpackt.", "Die Maschine war gebraucht, das wusste der Käufer.", "Der Preis war fair."], "falsch": 1},
  {"nr": 74, "art": "S", "zeuge": "F75", "beweis": null, "etikett": null, "saetze": ["Ich habe am Telefon nichts bestellt.", "Ich habe sofort aufgelegt.", "Ich habe das Abo bestellt, weil es so günstig klang."], "falsch": 2},
  {"nr": 75, "art": "S", "zeuge": "M20", "beweis": null, "etikett": null, "saetze": ["Ich habe den Vertreter nicht hereingelassen.", "Wir sprachen an der Tür.", "So war es wirklich.", "Im Wohnzimmer zeigte er mir die Prospekte."], "falsch": 3},
  {"nr": 76, "art": "S", "zeuge": "F35", "beweis": null, "etikett": null, "saetze": ["Der Handwerker kam pünktlich um acht.", "Wir haben bis mittags auf ihn gewartet.", "Er arbeitete bis zum Abend."], "falsch": 1},
  {"nr": 77, "art": "S", "zeuge": "M60", "beweis": null, "etikett": null, "saetze": ["Das Auto hatte keinen Unfall.", "Das habe ich geprüft.", "Nach dem Unfallschaden wurde es gut repariert."], "falsch": 2},
  {"nr": 78, "art": "S", "zeuge": "F75", "beweis": null, "etikett": null, "saetze": ["Ich habe den Widerruf rechtzeitig geschickt.", "Nach drei Tagen.", "Ich habe es selbst erlebt.", "Den Widerruf habe ich erst nach einem Monat abgeschickt."], "falsch": 3},
  {"nr": 79, "art": "S", "zeuge": "M20", "beweis": null, "etikett": null, "saetze": ["Der Fernseher war beim Auspacken heil.", "Schon im Karton war der Bildschirm zersprungen.", "Den Karton habe ich aufgehoben."], "falsch": 1},
  {"nr": 80, "art": "S", "zeuge": "F35", "beweis": null, "etikett": null, "saetze": ["Wir haben einen Festpreis vereinbart.", "2.000 Euro.", "Ein Preis wurde nie besprochen."], "falsch": 2},
  {"nr": 81, "art": "S", "zeuge": "M60", "beweis": null, "etikett": null, "saetze": ["Ich bin der Verkäufer des Autos.", "Es war ein Familienauto.", "Daran gibt es keinen Zweifel.", "Ich habe das Auto nie gesehen, bevor es verkauft war."], "falsch": 3},
  {"nr": 82, "art": "S", "zeuge": "F75", "beweis": null, "etikett": null, "saetze": ["Die Reise war ausgebucht.", "Unser Zimmer hatte Meerblick und war wunderschön.", "Wir bekamen kein Zimmer."], "falsch": 1},
  {"nr": 83, "art": "S", "zeuge": "M20", "beweis": null, "etikett": null, "saetze": ["Das Paket kam nie an.", "Ich will mein Geld zurück.", "Ich habe das Paket geöffnet und die falsche Farbe gesehen."], "falsch": 2},
  {"nr": 84, "art": "S", "zeuge": "F35", "beweis": null, "etikett": null, "saetze": ["Ich kündige jeden Vertrag schriftlich.", "Immer per Brief.", "Das habe ich damals schon so gesagt.", "Ich habe das Studio nur mündlich an der Theke gekündigt."], "falsch": 3},
  {"nr": 85, "art": "S", "zeuge": "M60", "beweis": null, "etikett": null, "saetze": ["Die Arbeit war mangelfrei.", "Wir wussten, dass die Fliesen schief waren.", "Der Kunde war zufrieden."], "falsch": 1},
  {"nr": 86, "art": "S", "zeuge": "F75", "beweis": null, "etikett": null, "saetze": ["Mein Hund ist ganz klein.", "Ein Dackel.", "Mein großer Schäferhund springt leicht über den Zaun."], "falsch": 2},
  {"nr": 87, "art": "S", "zeuge": "M60", "beweis": null, "etikett": null, "saetze": ["Der Baum steht auf meinem Grundstück.", "Die Äste ragen über den Zaun.", "Das weiß ich noch genau.", "Der Baum gehört dem Nachbarn, ich habe damit nichts zu tun."], "falsch": 3},
  {"nr": 88, "art": "S", "zeuge": "F35", "beweis": null, "etikett": null, "saetze": ["Ich habe am Morgen um sechs gestreut.", "Ich bin erst mittags aufgestanden.", "Die Frau ist trotzdem gestürzt."], "falsch": 1},
  {"nr": 89, "art": "S", "zeuge": "M20", "beweis": null, "etikett": null, "saetze": ["Ich habe nicht Fußball gespielt.", "Ich habe nur zugeschaut.", "Mein Schuss ging leider etwas zu hoch."], "falsch": 2},
  {"nr": 90, "art": "S", "zeuge": "F75", "beweis": null, "etikett": null, "saetze": ["Der Zaun stand schon, als ich einzog.", "Er ist aus Holz.", "Daran erinnere ich mich gut.", "Ich habe den Zaun selbst gebaut, ein schönes Stück Arbeit."], "falsch": 3},
  {"nr": 91, "art": "S", "zeuge": "M60", "beweis": null, "etikett": null, "saetze": ["Ich habe mir das Geld nie geliehen.", "Ich wollte das Geld ja zurückzahlen, nur später.", "Es waren 5.000 Euro."], "falsch": 1},
  {"nr": 92, "art": "S", "zeuge": "F35", "beweis": null, "etikett": null, "saetze": ["Ich grille nie.", "Ich mag das nicht.", "Jeden Sonntag grillen wir mit der ganzen Familie."], "falsch": 2},
  {"nr": 93, "art": "S", "zeuge": "M20", "beweis": null, "etikett": null, "saetze": ["Ich bin langsam Ski gefahren.", "Ganz vorsichtig.", "Da bin ich mir ganz sicher.", "Ich bin so schnell gefahren, dass ich nicht mehr bremsen konnte."], "falsch": 3},
  {"nr": 94, "art": "S", "zeuge": "F75", "beweis": null, "etikett": null, "saetze": ["Ich habe das Foto nie gesehen.", "Das Foto im Internet hat mich sehr geärgert.", "Ich will, dass es gelöscht wird."], "falsch": 1},
  {"nr": 95, "art": "S", "zeuge": "M60", "beweis": null, "etikett": null, "saetze": ["Die Risse waren schon vor den Bauarbeiten da.", "Die Wand muss repariert werden.", "Erst nach den Bauarbeiten bemerkte ich die Risse."], "falsch": 2},
  {"nr": 96, "art": "S", "zeuge": "F35", "beweis": null, "etikett": null, "saetze": ["Ich habe keine Drohne.", "So etwas interessiert mich nicht.", "Ich habe nie eine besessen.", "Meine Drohne fliegt nur über meinem eigenen Garten."], "falsch": 3},
  {"nr": 97, "art": "S", "zeuge": "M20", "beweis": null, "etikett": null, "saetze": ["Ich bin nicht der Pferdebesitzer.", "Mein Pferd ist sonst ganz brav.", "Die Reiterin ist gestürzt."], "falsch": 1},
  {"nr": 98, "art": "S", "zeuge": "F75", "beweis": null, "etikett": null, "saetze": ["Ich habe den Mahnbescheid nie bekommen.", "Ich schulde niemandem etwas.", "Den Mahnbescheid habe ich weggeworfen."], "falsch": 2},
  {"nr": 99, "art": "S", "zeuge": "M60", "beweis": null, "etikett": null, "saetze": ["Der Hund war angeleint.", "Er hat die Frau gebissen.", "So war es wirklich.", "Der Hund lief frei auf der Wiese herum."], "falsch": 3},
  {"nr": 100, "art": "S", "zeuge": "F35", "beweis": null, "etikett": null, "saetze": ["Ich war zum Zeitpunkt des Unfalls im Laden.", "Ich war schon zu Hause, als ich vom Unfall hörte.", "Ein Auto hatte den Radfahrer erfasst."], "falsch": 1},
];
